function w({registerIndicator:p,sourceValues:h,nulls:m}){p({id:"oa-apo",name:"Absolute Price Oscillator (APO)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"fastLength",type:"number",label:"Fast Length",default:12,min:1,max:5e3,step:1},{key:"slowLength",type:"number",label:"Slow Length",default:26,min:1,max:5e3,step:1}],plots:[{key:"apo",type:"line",title:"APO",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,c){const N=Math.max(1,Math.floor(Number(c.fastLength)||12)),y=Math.max(1,Math.floor(Number(c.slowLength)||26)),b=h(n,c.source??"close"),g=2/(N+1),r=2/(y+1),u=new Array(n.length).fill(NaN);let e=NaN,t=NaN,a=1,i=!0,o=NaN;for(let s=0;s<n.length;s++){const l=b[s];if(Number.isFinite(l))if(!Number.isFinite(e))e=l,t=l,o=0;else if(e=g*(l-e)+e,t=r*(l-t)+t,i){a*=1-r;const f=a>1e-10?1/(1-a):1;o=e*f-t*f,a<=1e-10&&(i=!1)}else o=e-t;u[s]=o}return{apo:m(u)}}})}export{w as default};
